def construct_bibd_matrix():
    v = 13
    k = 3
    lam = 2
    b = 52

    base_blocks = [(0, 1, 2), (0, 2, 6), (0, 3, 7), (0, 3, 8)]

    # Generate all blocks by cyclic development
    all_blocks = []
    for base in base_blocks:
        for shift in range(v):
            block = tuple((x + shift) % v for x in base)
            all_blocks.append(block)

    print(f"Total blocks: {len(all_blocks)}")

    # Create incidence matrix
    matrix = [[0] * b for _ in range(v)]
    for j, block in enumerate(all_blocks):
        for point in block:
            matrix[point][j] = 1

    # Verify row sums (should be r=12)
    for i in range(v):
        row_sum = sum(matrix[i])
        if row_sum != 12:
            print(f"Row {i} sum = {row_sum}, expected 12")

    # Verify column sums (should be k=3)
    for j in range(b):
        col_sum = sum(matrix[i][j] for i in range(v))
        if col_sum != 3:
            print(f"Column {j} sum = {col_sum}, expected 3")

    # Verify pairwise inner products (should be lam=2)
    for i1 in range(v):
        for i2 in range(i1+1, v):
            inner = sum(matrix[i1][j] * matrix[i2][j] for j in range(b))
            if inner != lam:
                print(f"Pair ({i1}, {i2}) inner product = {inner}, expected {lam}")

    print("All checks passed!")

    # Flatten matrix
    flat = []
    for i in range(v):
        for j in range(b):
            flat.append(matrix[i][j])

    return flat

flat_matrix = construct_bibd_matrix()
print(f"Matrix size: {len(flat_matrix)}")
print(f"First 52 elements: {flat_matrix[:52]}")
